CREATE POLICY "Authenticated users view user media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'user-media');
CREATE POLICY "Users upload own media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'user-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users update own media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'user-media' AND owner_id = auth.uid()::text) WITH CHECK (bucket_id = 'user-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'user-media' AND owner_id = auth.uid()::text);